// pubspec.yaml: mobile_scanner: ^5.0.0
import 'package:mobile_scanner/mobile_scanner.dart';

class ScanScreen extends StatefulWidget {
  const ScanScreen({super.key});
  @override State<ScanScreen> createState() => _ScanScreenState();
}

class _ScanScreenState extends State<ScanScreen> with WidgetsBindingObserver {
  final _ctrl = MobileScannerController(
    formats: const [BarcodeFormat.qrCode, BarcodeFormat.ean13, BarcodeFormat.dataMatrix],
    detectionSpeed: DetectionSpeed.noDuplicates,   // dedup same barcode
    detectionTimeoutMs: 250,
    cameraResolution: const Size(1280, 720),
    facing: CameraFacing.back,
    torchEnabled: false,
    returnImage: false,   // set true only if you need the raw frame
  );

  String? _lastCode;

  @override void initState() { super.initState(); WidgetsBinding.instance.addObserver(this); _ctrl.start(); }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.paused) _ctrl.stop();
    if (state == AppLifecycleState.resumed) _ctrl.start();
  }

  void _onDetect(BarcodeCapture capture) {
    for (final b in capture.barcodes) {
      if (b.rawValue == null || b.rawValue == _lastCode) continue;
      _lastCode = b.rawValue;
      HapticFeedback.mediumImpact();
      Navigator.of(context).pop({'code': b.rawValue, 'format': b.format.name});
      return;
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('Scan barcode'), actions: [
        IconButton(icon: const Icon(Icons.flash_on),
          onPressed: () => _ctrl.toggleTorch()),
        IconButton(icon: const Icon(Icons.cameraswitch),
          onPressed: () => _ctrl.switchCamera()),
      ]),
      body: Stack(children: [
        MobileScanner(controller: _ctrl, onDetect: _onDetect),
        // Overlay: scan rectangle centered
        Center(
          child: Container(
            width: 260, height: 260,
            decoration: BoxDecoration(
              border: Border.all(color: Colors.white70, width: 3),
              borderRadius: BorderRadius.circular(12),
            ),
          ),
        ),
      ]),
    );
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    _ctrl.dispose();
    super.dispose();
  }
}
